3	module ExceptionUnit(
4	    input clk, rst,
5	    input csr_rw_in,
6	    // write/set/clear (funct bits from instruction)
7	    input[1:0] csr_wsc_mode_in,
8	    input csr_w_imm_mux,
9	    input[11:0] csr_rw_addr_in,
10	    input[31:0] csr_w_data_reg,
11	    input[4:0] csr_w_data_imm,
12	    output[31:0] csr_r_data_out,
13	
14	    input interrupt,
15	    input illegal_inst,
16	    input l_access_fault,
17	    input s_access_fault,
18	    input ecall_m,
19	
20	    input mret,
21	
22	    input[31:0] epc_cur,
23	    input[31:0] epc_next,
24	    output[31:0] PC_redirect,
25	    output redirect_mux,
26	
27	    output reg_FD_flush, reg_DE_flush, reg_EM_flush, reg_MW_flush, 
28	    output RegWrite_cancel,
29	    output MemWrite_cancel
30	);
31	    // According to the diagram, design the Exception Unit
32	    // You can modify any code in this file if needed!
33	    reg[11:0] csr_waddr;
34	    reg[31:0] csr_wdata;
35	    reg csr_w;
36	    reg[1:0] csr_wsc;
37	    wire[11:0] csr_raddr;
38	
39	    wire[31:0] mstatus;
40	    wire[31:0] csr_rdata;
41	
42	    CSRRegs csr(.clk(clk),.rst(rst),.csr_w(csr_w),.raddr(csr_raddr),.waddr(csr_waddr),
43	        .wdata(csr_wdata),.rdata(csr_rdata),.mstatus(mstatus),.csr_wsc_mode(csr_wsc));
44	
45	    // ---------------- exception handling logic ----------------
46	    // synchronous exceptions are raised when the faulting instruction reaches WB;
47	    // interrupt is external and refers to the next instruction to execute
48	    wire sync_exc = illegal_inst | ecall_m | l_access_fault | s_access_fault;
49	    wire interrupt_en = interrupt & mstatus[3];     // mstatus.MIE
50	    wire trap = sync_exc | interrupt_en;
51	
52	    // mcause: illegal=2, l_access_fault=5, s_access_fault=7, ecall=11,
53	    //         machine external interrupt=0x8000000b
54	    reg[31:0] cause;
55	    always @(*) begin
56	        if (illegal_inst)         cause = 32'd2;
57	        else if (ecall_m)         cause = 32'd11;
58	        else if (l_access_fault)  cause = 32'd5;
59	        else if (s_access_fault)  cause = 32'd7;
60	        else                      cause = 32'h8000000b;
61	    end
62	
63	    // mepc: faulting instruction for sync exceptions, next PC for interrupt
64	    wire[31:0] mepc_in = sync_exc ? epc_cur : epc_next;
65	    // mtval: no faulting instruction/address information is available
66	    // through the fixed ports of this unit, so it is written as 0
67	    wire[31:0] mtval_in = 32'b0;
68	
69	    // trap entry:  MPP <- 11, MPIE <- MIE, MIE <- 0
70	    wire[31:0] mstatus_trap = {mstatus[31:13], 2'b11, mstatus[10:8],
71	                               mstatus[3], mstatus[6:4], 1'b0, mstatus[2:0]};
72	    // mret:        MPP <- 00, MPIE <- 1, MIE <- MPIE
73	    wire[31:0] mstatus_mret = {mstatus[31:13], 2'b00, mstatus[10:8],
74	                               1'b1, mstatus[6:4], mstatus[7], mstatus[2:0]};
75	
76	    // On a trap several CSRs must be updated through the single write port:
77	    // mepc is written in the detection cycle, then a small FSM writes
78	    // mcause, mtval and mstatus in the following three cycles. The trap
79	    // handler reaches MEM at least 4 cycles after the redirect, so all
80	    // values are in place before they can be read.
81	    localparam ST_IDLE    = 3'd0;
82	    localparam ST_MCAUSE  = 3'd1;
83	    localparam ST_MTVAL   = 3'd2;
84	    localparam ST_MSTATUS = 3'd3;
85	
86	    reg[2:0] state;
87	    reg[31:0] saved_cause, saved_mtval, saved_mstatus;
88	
89	    // CSR read address: trap -> mtvec, mret -> mepc, otherwise the
90	    // address of the CSR instruction currently in MEM
91	    assign csr_raddr = trap ? 12'h305 :
92	                       mret ? 12'h341 : csr_rw_addr_in;
93	    assign csr_r_data_out = csr_rdata;
94	
95	    // PC redirect: trap -> mtvec, mret -> mepc (both via csr_rdata)
96	    assign PC_redirect = csr_rdata;
97	    assign redirect_mux = trap | mret;
98	
99	    // pipeline flush: a trap kills every in-flight instruction (the one in
100	    // WB is cancelled below); mret only kills the younger wrong-path ones
101	    assign reg_FD_flush = trap | mret;
102	    assign reg_DE_flush = trap | mret;
103	    assign reg_EM_flush = trap | mret;
104	    assign reg_MW_flush = trap;
105	    assign RegWrite_cancel = trap;
106	    assign MemWrite_cancel = trap;
107	
108	    // normal CSR instruction write (MEM stage). For set/clear modes a zero
109	    // source (rs1 = x0 / uimm = 0) must not modify the CSR.
110	    wire csr_w_normal = csr_rw_in & ~(csr_wsc_mode_in[1] & (csr_w_data_imm == 5'b0));
111	    wire[31:0] csr_wdata_normal = csr_w_imm_mux ? {27'b0, csr_w_data_imm} : csr_w_data_reg;
112	
113	    // CSR write port mux: trap/FSM/mret have priority over normal CSR writes
114	    always @(*) begin
115	        if (trap) begin
116	            csr_w = 1'b1; csr_waddr = 12'h341; csr_wdata = mepc_in; csr_wsc = 2'b01;
117	        end
118	        else if (state == ST_MCAUSE) begin
119	            csr_w = 1'b1; csr_waddr = 12'h342; csr_wdata = saved_cause; csr_wsc = 2'b01;
120	        end
121	        else if (state == ST_MTVAL) begin
122	            csr_w = 1'b1; csr_waddr = 12'h343; csr_wdata = saved_mtval; csr_wsc = 2'b01;
123	        end
124	        else if (state == ST_MSTATUS) begin
125	            csr_w = 1'b1; csr_waddr = 12'h300; csr_wdata = saved_mstatus; csr_wsc = 2'b01;
126	        end
127	        else if (mret) begin
128	            csr_w = 1'b1; csr_waddr = 12'h300; csr_wdata = mstatus_mret; csr_wsc = 2'b01;
129	        end
130	        else begin
131	            csr_w = csr_w_normal; csr_waddr = csr_rw_addr_in;
132	            csr_wdata = csr_wdata_normal; csr_wsc = csr_wsc_mode_in;
133	        end
134	    end
135	
136	    always @(posedge clk or posedge rst) begin
137	        if (rst) begin
138	            state <= ST_IDLE;
139	            saved_cause <= 0;
140	            saved_mtval <= 0;
141	            saved_mstatus <= 0;
142	        end
143	        else if (trap) begin
144	            state <= ST_MCAUSE;
145	            saved_cause <= cause;
146	            saved_mtval <= mtval_in;
147	            saved_mstatus <= mstatus_trap;
148	        end
149	        else if (state == ST_MCAUSE)  state <= ST_MTVAL;
150	        else if (state == ST_MTVAL)   state <= ST_MSTATUS;
151	        else if (state == ST_MSTATUS) state <= ST_IDLE;
152	    end
153	
154	endmodule

