3	module RAM_B(
4	    input [31:0] addra,
5	    input clka,      // normal clock
6	    input[31:0] dina,
7	    input wea,
8	    input rea,
9	    output[31:0] douta,
10	    input[2:0] mem_u_b_h_w,
11	    output l_access_fault, s_access_fault
12	);
13	
14	    (* ram_style = "block" *) reg[7:0] data[0:127];
15	
16	    initial	begin
17	        $readmemh("ram.mem", data);
18	    end
19	
20	    // byte/halfword/word write logic
21	    // Write occurs on negedge clka when wea is asserted and address is in range
22	    wire in_range = ~|addra[31:7];
23	    wire[6:0] a0 = addra[6:0];
24	
25	    always @(negedge clka) begin
26	        if (wea && in_range) begin
27	            case (mem_u_b_h_w[1:0])
28	                2'b00: data[a0] <= dina[7:0];                                  // SB
29	                2'b01: begin                                                   // SH
30	                    data[a0] <= dina[7:0];
31	                    if (a0 < 7'h7f) data[a0+1] <= dina[15:8];
32	                end
33	                2'b10: begin                                                   // SW
34	                    data[a0] <= dina[7:0];
35	                    if (a0 < 7'h7f) data[a0+1] <= dina[15:8];
36	                    if (a0 < 7'h7e) data[a0+2] <= dina[23:16];
37	                    if (a0 < 7'h7d) data[a0+3] <= dina[31:24];
38	                end
39	                default: ;
40	            endcase
41	        end
42	    end
43	
44	    // byte/halfword/word read logic with sign extension
45	    // out-of-range bytes read as 0 to avoid X propagation
46	    wire[7:0] b0 = in_range ? data[a0] : 8'h0;
47	    wire[7:0] b1 = (in_range && a0 < 7'h7f) ? data[a0+1] : 8'h0;
48	    wire[7:0] b2 = (in_range && a0 < 7'h7e) ? data[a0+2] : 8'h0;
49	    wire[7:0] b3 = (in_range && a0 < 7'h7d) ? data[a0+3] : 8'h0;
50	
51	    wire[31:0] word_rd = {b3, b2, b1, b0};
52	    wire[31:0] half_rd = mem_u_b_h_w[2] ? {16'b0, b1, b0} : {{16{b1[7]}}, b1, b0};
53	    wire[31:0] byte_rd = mem_u_b_h_w[2] ? {24'b0, b0} : {{24{b0[7]}}, b0};
54	
55	    assign douta = mem_u_b_h_w[1] ? word_rd :
56	                   mem_u_b_h_w[0] ? half_rd : byte_rd;
57	    
58	    assign l_access_fault = rea & |addra[31:7];
59	    assign s_access_fault = wea & |addra[31:7];
60	
61	endmodule

