`timescale 1ns / 1ps
// WB-stage monitor for lab2 RV32core running the pre-loaded rom.mem program.
// Run vvp from a directory containing rom.mem/ram.mem (lab2/core).
module tb_lab2;
    reg clk, rst;
    integer cycle = 0;
    integer errors = 0;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'b0),
        .debug_data(),
        .clk(clk),
        .rst(rst),
        .wb_pc(),
        .wb_inst(),
        .mem_addr(),
        .mem_data(),
        .interrupter(1'b0)
    );

    initial begin
        clk = 0;
        rst = 1;
        #2 rst = 0;
    end
    always #1 clk = ~clk;

    // log every WB-stage register write (the value latched into Regs at this edge)
    always @(posedge clk) begin
        cycle = cycle + 1;
        if (!rst) begin
            if (core.RegWrite_WB && !core.RegWrite_cancel_exp) begin
                if (^core.wt_data_WB === 1'bx || ^core.rd_WB === 1'bx || ^core.PC_WB === 1'bx) begin
                    $display("XPROP cycle=%0d pc=%h inst=%h rd=%h data=%h",
                             cycle, core.PC_WB, core.inst_WB, core.rd_WB, core.wt_data_WB);
                    errors = errors + 1;
                end else if (core.rd_WB != 5'd0) begin
                    $display("WB cycle=%0d pc=%h inst=%h rd=x%0d data=%h",
                             cycle, core.PC_WB, core.inst_WB, core.rd_WB, core.wt_data_WB);
                end
            end
            if (core.redirect_mux_exp)
                $display("REDIRECT cycle=%0d to pc=%h (trap=%b mret=%b cause_pending)",
                         cycle, core.PC_redirect_exp,
                         core.exp_unit.trap, core.mret_MEM);
        end
        if (cycle > 500) begin
            $display("DONE errors=%0d", errors);
            $finish;
        end
    end
endmodule

