`timescale 1ns / 1ps
// Self-checking WB-stage monitor for lab2 RV32core running rom.mem.
// Golden trace hand-derived from lab2/exp_test.s + ram.mem.
// Run vvp from a directory containing rom.mem/ram.mem (lab2/core).
module tb_lab2_check;
    reg clk, rst;
    integer cycle = 0;
    integer idx = 0;      // index into golden table
    integer errors = 0;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'b0),
        .debug_data(),
        .clk(clk),
        .rst(rst),
        .wb_pc(),
        .wb_inst(),
        .mem_addr(),
        .mem_data(),
        .interrupter(1'b0)
    );

    // golden table: {pc[31:0], rd[4:0], data[31:0]}
    localparam N = 40;
    reg [68:0] golden [0:N-1];
    initial begin
        // main: loads
        golden[ 0] = {32'h04, 5'd2,  32'h00000008}; // lw x2,4(x0)
        golden[ 1] = {32'h08, 5'd4,  32'h00000010}; // lw x4,8(x0)
        golden[ 2] = {32'h0c, 5'd5,  32'h00000014}; // lw x5,12(x0)
        golden[ 3] = {32'h10, 5'd6,  32'hffff0000}; // lw x6,16(x0)
        golden[ 4] = {32'h14, 5'd7,  32'h0fff0000}; // lw x7,20(x0)
        // main: CSR ops on 0x306
        golden[ 5] = {32'h18, 5'd1,  32'h00000000}; // csrrwi x1,0x306,16 (old=0)
        golden[ 6] = {32'h1c, 5'd1,  32'h00000010}; // csrr x1,0x306
        golden[ 7] = {32'h20, 5'd1,  32'h00000010}; // csrrw x1,0x306,x6 (old=0x10)
        golden[ 8] = {32'h24, 5'd1,  32'hffff0000}; // csrr x1,0x306
        golden[ 9] = {32'h2c, 5'd1,  32'h00000078}; // addi x1,x0,120
        // trap 1: ecall @0x38 -> handler
        golden[10] = {32'h78, 5'd25, 32'h00000038}; // csrr x25,mepc
        golden[11] = {32'h7c, 5'd27, 32'h0000000b}; // csrr x27,mcause
        golden[12] = {32'h80, 5'd28, 32'h00001880}; // csrr x28,mstatus
        golden[13] = {32'h84, 5'd29, 32'h00000000}; // csrr x29,mtval
        golden[14] = {32'h88, 5'd30, 32'h00000000}; // csrr x30,mip
        golden[15] = {32'h8c, 5'd2,  32'h0000003c}; // addi x2,x25,4
        // trap 2: illegal @0x40 -> handler
        golden[16] = {32'h78, 5'd25, 32'h00000040};
        golden[17] = {32'h7c, 5'd27, 32'h00000002};
        golden[18] = {32'h80, 5'd28, 32'h00001880};
        golden[19] = {32'h84, 5'd29, 32'h00000012}; // mtval = faulting inst
        golden[20] = {32'h88, 5'd30, 32'h00000000};
        golden[21] = {32'h8c, 5'd2,  32'h00000044};
        // lw x1,127(x0) @0x48 (in range, byte=0)
        golden[22] = {32'h48, 5'd1,  32'h00000000};
        // trap 3: load access fault @0x4c -> handler
        golden[23] = {32'h78, 5'd25, 32'h0000004c};
        golden[24] = {32'h7c, 5'd27, 32'h00000005};
        golden[25] = {32'h80, 5'd28, 32'h00001880};
        golden[26] = {32'h84, 5'd29, 32'h00000080}; // mtval = faulting addr
        golden[27] = {32'h88, 5'd30, 32'h00000000};
        golden[28] = {32'h8c, 5'd2,  32'h00000050};
        // trap 4: store access fault @0x54 -> handler
        golden[29] = {32'h78, 5'd25, 32'h00000054};
        golden[30] = {32'h7c, 5'd27, 32'h00000007};
        golden[31] = {32'h80, 5'd28, 32'h00001880};
        golden[32] = {32'h84, 5'd29, 32'h00000080}; // mtval = faulting addr
        golden[33] = {32'h88, 5'd30, 32'h00000000};
        golden[34] = {32'h8c, 5'd2,  32'h00000058};
        // jr x0 @0x74 -> second pass starts (CSR[6] now 0xffff0000)
        golden[35] = {32'h04, 5'd2,  32'h00000008};
        golden[36] = {32'h18, 5'd1,  32'hffff0000}; // csrrwi old=0xffff0000
        golden[37] = {32'h1c, 5'd1,  32'h00000010};
        golden[38] = {32'h20, 5'd1,  32'h00000010};
        golden[39] = {32'h24, 5'd1,  32'hffff0000};
    end

    initial begin
        clk = 0;
        rst = 1;
        #2 rst = 0;
    end
    always #1 clk = ~clk;

    always @(posedge clk) begin
        cycle = cycle + 1;
        if (!rst) begin
            if (core.RegWrite_WB && !core.RegWrite_cancel_exp) begin
                if (^core.wt_data_WB === 1'bx || ^core.rd_WB === 1'bx || ^core.PC_WB === 1'bx) begin
                    $display("FAIL X-prop cycle=%0d pc=%h rd=%h data=%h",
                             cycle, core.PC_WB, core.rd_WB, core.wt_data_WB);
                    errors = errors + 1;
                end else if (core.rd_WB != 5'd0) begin
                    if (idx < N) begin
                        if ({core.PC_WB, core.rd_WB, core.wt_data_WB} !== golden[idx]) begin
                            $display("FAIL idx=%0d cycle=%0d got pc=%h rd=x%0d data=%h, expected pc=%h rd=x%0d data=%h",
                                     idx, cycle, core.PC_WB, core.rd_WB, core.wt_data_WB,
                                     golden[idx][68:37], golden[idx][36:32], golden[idx][31:0]);
                            errors = errors + 1;
                        end else begin
                            $display("PASS idx=%0d cycle=%0d pc=%h rd=x%0d data=%h",
                                     idx, cycle, core.PC_WB, core.rd_WB, core.wt_data_WB);
                        end
                        idx = idx + 1;
                    end
                end
            end
        end
        if (cycle > 200) begin
            if (idx < N) begin
                $display("FAIL only %0d of %0d expected WB writes observed", idx, N);
                errors = errors + 1;
            end
            $display("RESULT errors=%0d checked=%0d", errors, idx);
            $finish;
        end
    end
endmodule
